-- Readonly Root/all92baseline/custody capture; actualtarget45 separately.
WITH root AS(SELECT to_jsonb(r)row_json,r.revision_sha256,r.canonical_preimage::jsonb tuple FROM mission_factory_owner.editor_release_readiness r WHERE singleton),
 wanted(signature)AS(SELECT x.value->>'signature'FROM root CROSS JOIN LATERAL jsonb_each(coalesce(tuple#>'{db_core,combat_innata_functions}','{}'::jsonb))x UNION SELECT x.value->>'signature'FROM root CROSS JOIN LATERAL jsonb_each(coalesce(tuple#>'{db_core,editor_panel_functions}','{}'::jsonb))x UNION SELECT x.value->>'signature'FROM root CROSS JOIN LATERAL jsonb_each(coalesce(tuple#>'{db_core,innata_staff_profile_functions}','{}'::jsonb))x UNION SELECT x.value->>'signature'FROM root CROSS JOIN LATERAL jsonb_each(coalesce(tuple#>'{db_core,sp07_cost_guard_functions}','{}'::jsonb))x UNION SELECT x.value->>'signature'FROM root CROSS JOIN LATERAL jsonb_each(coalesce(tuple#>'{db_core,sp08_rotation_probe_functions}','{}'::jsonb))x),
 funcs AS(SELECT f.* FROM wanted w CROSS JOIN LATERAL(SELECT w.signature,p.oid,n.nspname,p.proname,p.proowner::regrole::text owner,p.proacl::text acl,p.proconfig config,p.prosecdef secdef,l.lanname language,p.provolatile::text volatility,p.proisstrict strict,p.proparallel::text parallel,p.proleakproof leakproof,p.prokind::text kind,p.proargnames arg_names,p.proargmodes arg_modes,p.proargtypes::text arg_types,pg_get_function_result(p.oid)returns,md5(p.prosrc)source_md5,md5(pg_get_functiondef(p.oid))ddl_md5 FROM(SELECT w.signature::text signature)w LEFT JOIN pg_proc p ON p.oid=to_regprocedure(w.signature)LEFT JOIN pg_namespace n ON n.oid=p.pronamespace LEFT JOIN pg_language l ON l.oid=p.prolang)f)
 SELECT jsonb_build_object('schema_version','combat-innata-backend-c-actual/1','captured_at',clock_timestamp(),'root_row',r.row_json,'root_row_sha256',public.combat_v2_sha256(r.row_json),'functions',(SELECT jsonb_agg(to_jsonb(f)ORDER BY signature)FROM funcs f),
 'release',(SELECT to_jsonb(a)FROM mission_public_owner.release_admissions_v1 a WHERE a.release_sha256=r.revision_sha256),
 'qualification',(SELECT to_jsonb(a)FROM mission_public_owner.public_qualification_attestations_v1 a WHERE a.release_sha256=r.revision_sha256),
 'profile',mission_public_owner.engine_profile_state_v1(r.revision_sha256,'mission-ai-authoring/1'),
 'content_admissions',(SELECT coalesce(jsonb_agg(to_jsonb(a)ORDER BY a.publication_request),'[]'::jsonb)FROM mission_public_owner.mission_content_admissions_v1 a WHERE a.engine_release_sha256=r.revision_sha256),
 'origin',(SELECT to_jsonb(a)FROM mission_public_owner.existing_publications_v1 a WHERE a.request_key='3ff627ec-dbee-423a-9879-8e37f7ad5510'::uuid),
 'capability',(SELECT to_jsonb(a)FROM mission_launch_owner.capabilities a WHERE a.mission_id='6d6c216a-222d-4cba-b2fc-f3e0c199c195'::uuid),
 'gates',jsonb_build_object('innata',(SELECT to_jsonb(g)FROM clan_innata_narrative_private.gate_v1 g WHERE singleton),'facing',(SELECT to_jsonb(g)FROM combat_facing_private.release_gate g WHERE singleton),'tactics',(SELECT to_jsonb(g)FROM combat_panel_private.multiplication_tactics_release_gate g WHERE singleton)),
 'staff_profile_group',coalesce(r.tuple#>'{db_core,innata_staff_profile_functions}','{}'::jsonb),
 'staff_profile_relations',(SELECT jsonb_agg(to_jsonb(v)ORDER BY v.name)FROM(VALUES('clan_innata_narrative_private.contexts_v1'),('clan_hyuga_private.staff_profiles'))w(name)CROSS JOIN LATERAL(SELECT w.name,c.oid,c.relkind::text kind,c.relowner::regrole::text owner,c.relacl::text acl,c.relrowsecurity rls,c.relforcerowsecurity force_rls,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid))ORDER BY a.attnum),'[]'::jsonb)FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)columns,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('name',x.conname,'ddl',pg_get_constraintdef(x.oid),'validated',x.convalidated)ORDER BY x.conname),'[]'::jsonb)FROM pg_constraint x WHERE x.conrelid=c.oid)constraints,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled::text,'ddl',pg_get_triggerdef(t.oid),'function_md5',md5(pg_get_functiondef(t.tgfoid)))ORDER BY t.tgname),'[]'::jsonb)FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)triggers,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('name',x.polname,'command',x.polcmd::text,'permissive',x.polpermissive,'roles',to_jsonb(x.polroles),'using',pg_get_expr(x.polqual,x.polrelid),'with_check',pg_get_expr(x.polwithcheck,x.polrelid))ORDER BY x.polname),'[]'::jsonb)FROM pg_policy x WHERE x.polrelid=c.oid)policies,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('name',x.indexrelid::regclass::text,'ddl',pg_get_indexdef(x.indexrelid))ORDER BY x.indexrelid::regclass::text),'[]'::jsonb)FROM pg_index x WHERE x.indrelid=c.oid)indexes,
 CASE WHEN c.relkind='v'THEN pg_get_viewdef(c.oid,true)END view FROM(SELECT w.name::text name)w LEFT JOIN pg_class c ON c.oid=to_regclass(w.name))v),
 'custody',jsonb_build_object('contexts',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY context_id),'[]'::jsonb)::text)FROM clan_innata_narrative_private.contexts_v1 x),'states',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x)ORDER BY context_id,technique_id),'[]'::jsonb)::text)FROM clan_innata_narrative_private.states_v1 x),'receipts',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x)ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)FROM clan_innata_narrative_private.receipts_v1 x),'scorta_master',(SELECT md5(to_jsonb(s)::text)FROM public.master_v2_sessions s WHERE id='93d78313-abde-4087-9eb7-7b96bc0fa089'),'scorta_mission',(SELECT md5(to_jsonb(s)::text)FROM public.missions s WHERE id='db1588ae-50f2-4c0e-9028-0b94155d94b1'),'PG',(SELECT jsonb_object_agg(name,md5((to_jsonb(c)-'updated_at'-'last_regen_at')::text))FROM public.characters c WHERE name IN('Riuji','Tamako','testperfunzioni'))),
 'checks',jsonb_build_object('staff_profile_group_consistent',CASE WHEN NOT(r.tuple->'db_core'? 'innata_staff_profile_functions')THEN true ELSE(SELECT count(*)=17 AND bool_and(x.value=(SELECT to_jsonb(f)FROM funcs f WHERE f.signature=x.value->>'signature'))FROM jsonb_each(r.tuple#>'{db_core,innata_staff_profile_functions}')x)END,'engine_qualified',mission_public_owner.engine_qualification_v1(r.revision_sha256,true)IS NOT NULL,'legacy_adopted',mission_public_owner.content_admission_v1('6d6c216a-222d-4cba-b2fc-f3e0c199c195',r.revision_sha256,'3ff627ec-dbee-423a-9879-8e37f7ad5510',true)IS NOT NULL,'scope',mission_public_owner.c1266_regia_public_scope_v1('6d6c216a-222d-4cba-b2fc-f3e0c199c195','ai','3ff627ec-dbee-423a-9879-8e37f7ad5510',r.revision_sha256),'existing_open',mission_public_owner.existing_release_assert_v2('3ff627ec-dbee-423a-9879-8e37f7ad5510','public')='6d6c216a-222d-4cba-b2fc-f3e0c199c195'::uuid))AS capture FROM root r;


